add_action('rest_api_init', function () {
    register_rest_route('sopucoder/v1', '/feedback', [
        'methods'             => WP_REST_Server::CREATABLE,
        'callback'            => 'sopucoder_handle_feedback_submission',
        'permission_callback' => function (WP_REST_Request $request) {
            // Require logged-in users with edit_posts permission
            return current_user_can('edit_posts');
        },
        'args'                => [
            'title' => [
                'required'          => true,
                'type'              => 'string',
                'sanitize_callback' => 'sanitize_text_field',
                'validate_callback' => function ($param) {
                    return !empty($param) && mb_strlen($param) <= 100;
                },
            ],
            'message' => [
                'required'          => true,
                'type'              => 'string',
                'sanitize_callback' => 'sanitize_textarea_field',
            ],
            '_wpnonce' => [
                'required' => true,
                'validate_callback' => function ($nonce) {
                    return wp_verify_nonce($nonce, 'wp_rest');
                },
            ],
        ],
    ]);
});

function sopucoder_handle_feedback_submission(WP_REST_Request $request): WP_REST_Response
{
    $title   = $request->get_param('title');
    $message = $request->get_param('message');
    $user_id = get_current_user_id();

    $post_id = wp_insert_post([
        'post_title'   => wp_strip_all_tags($title),
        'post_content' => wp_kses_post($message),
        'post_status'  => 'publish',
        'post_type'    => 'user_feedback',
        'post_author'  => $user_id,
    ], true);

    if (is_wp_error($post_id)) {
        return new WP_REST_Response([
            'success' => false,
            'message' => $post_id->get_error_message(),
        ], 500);
    }

    return new WP_REST_Response([
        'success' => true,
        'feedback_id' => $post_id,
    ], 201);
}
