class SopuCoder_Analytics_Repository
{
    private string $table_name;

    public function __construct()
    {
        global $wpdb;
        $this->table_name = $wpdb->prefix . 'sopucoder_logs';
    }

    /**
     * Retrieves recent user activity logs with prepared SQL and caching.
     *
     * @param int $user_id
     * @param int $limit
     * @return array
     */
    public function get_user_logs(int $user_id, int $limit = 20): array
    {
        global $wpdb;
        $cache_key = "sopucoder_logs_{$user_id}_{$limit}";
        $cached = get_transient($cache_key);

        if (false !== $cached) {
            return (array) $cached;
        }

        // Always use prepare to prevent SQL injection vulnerabilities
        $query = $wpdb->prepare(
            "SELECT id, event_type, ip_address, created_at 
             FROM {$this->table_name} 
             WHERE user_id = %d 
             ORDER BY created_at DESC 
             LIMIT %d",
            $user_id,
            $limit
        );

        $results = $wpdb->get_results($query, ARRAY_A);
        $safe_results = is_array($results) ? $results : [];

        // Cache for 10 minutes (600 seconds)
        set_transient($cache_key, $safe_results, 600);

        return $safe_results;
    }
}
